"""Freeze exact 45-pose native entry-cell delta with preserved copper ledger."""
from pathlib import Path
import pcbnew,argparse,json,hashlib
from hardware_route_logic_return import pad_identity,identity
ROOT=Path(__file__).resolve().parents[1]
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
    ap=argparse.ArgumentParser();ap.add_argument('--base',type=Path,required=True);ap.add_argument('--board',type=Path,required=True);ap.add_argument('--fit',type=Path,required=True);ap.add_argument('--route',type=Path,required=True);ap.add_argument('--cleanup',type=Path,required=True);ap.add_argument('--output',type=Path,required=True);a=ap.parse_args();fit=json.loads(a.fit.read_text());rt=json.loads(a.route.read_text());cl=json.loads(a.cleanup.read_text());assert sha(a.base)==fit['source_sha256']and sha(a.board)==cl['candidate_sha256'];old=pcbnew.LoadBoard(str(a.base.resolve()));new=pcbnew.LoadBoard(str(a.board.resolve()));scope=set(fit['scope_refs']);assert len(scope)==45;op={p.m_Uuid.AsString():p for p in old.GetPads()};np={p.m_Uuid.AsString():p for p in new.GetPads()};assert set(op)==set(np)
    for uid,p in op.items():
        q=np[uid];assert p.GetNetname()==q.GetNetname()and p.GetSize()==q.GetSize()and p.GetShape()==q.GetShape()and p.GetNumber()==q.GetNumber()
        if p.GetParentFootprint().GetReference()not in scope:assert pad_identity(p)==pad_identity(q)
    oc={t.m_Uuid.AsString():identity(t)for t in old.GetTracks()};nc={t.m_Uuid.AsString():identity(t)for t in new.GetTracks()};removed=fit['exact_removed_private_copper']+rt['exact_removed_private_copper']+cl['exact_removed_old_entry_copper'];ids={r['uuid']for r in removed};assert len(ids)==len(removed);assert set(oc)-set(nc)==ids;assert all(nc[k]==v for k,v in oc.items()if k not in ids);added=rt['exact_added_copper'];assert set(nc)-set(oc)=={r['uuid']for r in added};assert all(json.loads(json.dumps(nc[r['uuid']]))==r['identity']for r in added);oldzones={z.m_Uuid.AsString()for z in old.Zones()};newzones={z.m_Uuid.AsString()for z in new.Zones()};assert newzones-oldzones=={r['uuid']for r in rt['exact_added_zones']};assert oldzones<=newzones
    proof=a.board.parent/'independent-native-connectivity.json';pv=json.loads(proof.read_text());assert pv['board_sha256']==sha(a.board)and pv['error_count']==0 and pv['actual_pin_checks']==105;neg=ROOT/'reports/motherboard-power-entry-20261001/entry-negative-cuts-r02/receipt.json';nv=json.loads(neg.read_text());assert nv['source_sha256']==sha(a.board)and nv['negative_copper_cuts']==9 and nv['all_detected'];host=a.board.parent/'host-regression.json';hv=json.loads(host.read_text());assert hv['passed']==269 and hv['exit_code']==0;assert not any(v['severity']=='error'for v in cl['native_remaining_violations'])
    files=[a.base,a.board,a.fit,a.route,a.cleanup,proof,neg,host,ROOT/'hardware/motherboard_power_entry/design.json',ROOT/'reports/motherboard-power-entry-20260930/sources/tps2663.pdf']+[ROOT/'tools'/n for n in ['hardware_power_entry_cell_layout.py','hardware_build_power_entry_fixture_native.py','hardware_fit_power_entry_cells_native.py','hardware_route_power_entry_cells_native.py','hardware_validate_power_entry_cells_native.py','hardware_retire_power_entry_stubs_native.py','hardware_test_power_entry_disconnect_native.py','hardware_freeze_power_entry_cells_native.py']]
    r=dict(base_board=str(a.base),base_sha256=sha(a.base),candidate_board=str(a.board),candidate_sha256=sha(a.board),source_hashes={str(p.resolve()):sha(p)for p in files},scope_refs=sorted(scope),exact_poses=fit['exact_poses'],groups=fit['groups'],exact_removed_copper=removed,exact_added_copper=added,exact_added_zones=rt['exact_added_zones'],moved_existing_parts=45,old_copper_removed=len(removed),new_copper_added=len(added),new_own_domain_zones=len(rt['exact_added_zones']),all_other_actual_pad_net_and_geometry_records_preserved=True,every_preexisting_unchanged_observer_connection_preserved=True,unchanged_observer_pads_checked=cl['observer_pads_checked'],additional_same_net_fill_connections=cl['observer_pads_with_additional_connections'],native_errors=0,native_drc_types=cl['native_drc_types'],remaining_native_violations=cl['native_remaining_violations'],actual_uncapped_missing_joins=pv['actual_uncapped_whole_board_missing_joins'],independent_actual_pin_checks=105,negative_actual_copper_cuts=9,host_tests_passed=269,manufacturing_ready=False,ampacity_qualified=False,global_terminal_feeders_closed=False,no_architecture_component_or_source_pin_changes=True)
    a.output.write_text(json.dumps(r,indent=2)+'\n');print(json.dumps({k:v for k,v in r.items()if k not in('source_hashes','scope_refs','exact_poses','groups','exact_removed_copper','exact_added_copper','exact_added_zones','remaining_native_violations')}))
if __name__=='__main__':main()
